/// Unified design tokens for the `child_dev` feature (Child Safety +
/// Child Alert, merged into one screen pair).
///
/// This replaces the two previously-separate palettes (`AxnColors`
/// from Child Alert and `ChildSafetyColors` from Child Safety) with a
/// single source of truth. Both original palettes already agreed on
/// every shared value (primary `#CE1126`, white surfaces, identical
/// opacity tints for success/warning/error/offline), so nothing was
/// renumbered — this is a straight merge.
class ChildDevColors {
  ChildDevColors._();

  // ---- base surfaces ----
  static Color bg(bool isLight) => isLight ? const Color(0xFFFFFFFF) : const Color(0xFF121212);
  static Color surface(bool isLight) => isLight ? const Color(0xFFFFFFFF) : const Color(0xFF1A1A1A);
  static Color card(bool isLight) => isLight ? const Color(0xFFFFFFFF) : const Color(0xFF212121);
  static Color cardRaised(bool isLight) => isLight ? const Color(0xFFF7F7F8) : const Color(0xFF2A2A2A);
  static Color hairline(bool isLight) => isLight ? const Color(0xFFE7E7E9) : const Color(0xFF3A3A3A);

  // ---- brand / primary ----
  static const Color primary = Color(0xFFCE1126);
  static const Color primaryBright = Color(0xFFE0142C);
  static const Color primaryDeep = Color(0xFFA10E1F);
  static Color primarySoft(bool isLight) => isLight ? const Color(0x1ACE1126) : const Color(0x1AE63946);
  static Color primaryText(bool isLight) => isLight ? primary : const Color(0xFFE63946);

  // ---- text ----
  static Color textHi(bool isLight) => isLight ? const Color(0xFF22252A) : const Color(0xFFF2F1EC);
  static Color textMid(bool isLight) => isLight ? const Color(0xFF6B7280) : const Color(0xFFB6B2A8);
  static Color textLow(bool isLight) => isLight ? const Color(0xFF9AA0A8) : const Color(0xFF9A9690);

  // ---- success (Child Found / normal) ----
  static const Color success = Color(0xFF5FAE72);
  static Color successBg(bool isLight) => isLight ? const Color(0x1F5FAE72) : const Color(0xFF0E2E20);
  static Color successBorder(bool isLight) => isLight ? const Color(0x475FAE72) : const Color(0xFF1F6B4A);
  static Color successIconWrapBg(bool isLight) => isLight ? const Color(0x335FAE72) : const Color(0xFF143828);
  static Color screenBorderFound(bool isLight) => isLight ? const Color(0x595FAE72) : const Color(0x665FAE72);

  // ---- warning (Active alert) ----
  static const Color warning = Color(0xFFDDA254);
  static const Color warningBright = Color(0xFFE8B46E);
  static Color warningBg(bool isLight) => isLight ? const Color(0x24DDA254) : const Color(0xFF332A14);
  static Color warningBorder(bool isLight) => isLight ? const Color(0x4DDDA254) : const Color(0xFFDDA254);
  static Color warningIconWrapBg(bool isLight) => isLight ? const Color(0x33DDA254) : const Color(0xFF3D3118);
  static Color screenBorderActive(bool isLight) => const Color(0x66DDA254);

  // ---- critical / error (Emergency) ----
  // Kept both names — `critical` (Child Alert) and `error` (Child
  // Safety) — since both referred to the exact same color already.
  static const Color critical = Color(0xFFCE1126);
  static const Color error = Color(0xFFCE1126);
  static const Color criticalBright = Color(0xFFE0142C);
  static Color criticalBg(bool isLight) => isLight ? const Color(0x17CE1126) : const Color(0xFF3F1218);
  static Color errorBg(bool isLight) => isLight ? const Color(0x17CE1126) : const Color(0xFF3F1218);
  static Color criticalBorder(bool isLight) => isLight ? const Color(0x47CE1126) : const Color(0xFFE63946);
  static Color criticalIconBg(bool isLight) => isLight ? const Color(0x24CE1126) : const Color(0xFF4A141B);
  static Color guidanceIconBg(bool isLight) => isLight ? const Color(0x1ACE1126) : const Color(0xFF2A0C10);

  // ---- offline (Signal lost) ----
  static const Color offline = Color(0xFF9AA0A8);
  static Color offlineBg(bool isLight) => isLight ? const Color(0x249AA0A8) : const Color(0xFF2A2A2A);
  static Color offlineBorder(bool isLight) => isLight ? const Color(0x4D9AA0A8) : const Color(0xFF555555);
  static Color offlineIconWrapBg(bool isLight) => isLight ? const Color(0x389AA0A8) : const Color(0xFF333333);
  static Color screenBorderUnavailable(bool isLight) => isLight ? const Color(0x669AA0A8) : const Color(0xFF555555);

  // ---- resolved ----
  static Color screenBorderResolved(bool isLight) => hairline(isLight);

  // ---- misc ----
  static Color primaryActionIconBg(bool isLight) => isLight ? const Color(0x2EFFFFFF) : const Color(0x2E000000);
  static const Color softShadow = Color(0x0A14141E);
  static const Color shadowMd = Color(0x0F14141E);
  static const Color shadowHover = Color(0x1214141E);
  static const Color primaryActionShadow = Color(0x73CE1126); // .45
  static const Color primaryActionShadowHover = Color(0x8CCE1126); // .55

  static const double radiusLg = 22;
  static const double radiusMd = 16;
  static const double radiusSm = 11;
}


