/// A single run of inline text, optionally bold.
///
/// Used to reproduce the original HTML's mixed `plain text <b>bold
/// text</b>` strings (e.g. alert meta lines and guidance copy)
/// without duplicating `RichText`/`TextSpan` boilerplate at every
/// call site.
class RichSegment {
  final String text;
  final bool bold;

  const RichSegment(this.text, {this.bold = false});
}

