// from: lib/child_dev/child_alert/models/child_alert_status.dart
// ---------------------------------------------------------------
/// The four mutually exclusive states the Child Alert screen can be
/// in, mirroring the original `setState('active' | 'found' |
/// 'resolved' | 'unavailable')` JavaScript function.
enum ChildAlertStatus {
  /// "Child Safety Alert" — child has left the Safe Zone.
  active,

  /// "Child Found" — child has been located and is safe.
  found,

  /// "Alert Resolved" — the alert has been closed and archived.
  resolved,

  /// "Location Unavailable" — signal from the child's device was lost.
  unavailable,
}

// ---------------------------------------------------------------
// from: lib/child_dev/child_alert/models/alert_state_content.dart
// ---------------------------------------------------------------
/// Content that is fully determined by the current [ChildAlertStatus]
/// alone — every field here is reassigned on every state transition
/// in the original JavaScript, so it is safe to compute fresh on
/// every build.
class AlertStateContent {
  final String title;
  final List<RichSegment> meta;
  final bool severityVisible;
  final List<RichSegment> guidance;
  final bool actionsVisible;
  final bool locationVisible;
  final bool resolvedVisible;
  final bool closeButtonVisible;
  final bool navigateDisabled;
  final bool ringPulseActive;
  final Color bannerBackground;
  final Color bannerBorder;
  final Color iconWrapBackground;
  final Color titleColor;
  final Color screenBorderColor;
  final Color brandDotColor;

  const AlertStateContent({
    required this.title,
    required this.meta,
    required this.severityVisible,
    required this.guidance,
    required this.actionsVisible,
    required this.locationVisible,
    required this.resolvedVisible,
    required this.closeButtonVisible,
    required this.navigateDisabled,
    required this.ringPulseActive,
    required this.bannerBackground,
    required this.bannerBorder,
    required this.iconWrapBackground,
    required this.titleColor,
    required this.screenBorderColor,
    required this.brandDotColor,
  });
}

/// Content that the original JavaScript only reassigns inside the
/// `active`, `found`, and `unavailable` branches of `setState()` —
/// never inside `resolved`. In the DOM this meant those elements
/// simply kept displaying whatever value was last written into them.
/// We reproduce that "sticky" behavior explicitly rather than
/// silently losing it in a stateless rebuild.
class AlertStickyContent {
  final Color avatarRingColor;
  final Color avatarDotColor;
  final String childStatusLine;
  final bool connPillOn;
  final String connPillText;
  final String locLabel;
  final String locValue;
  final String locTime;

  const AlertStickyContent({
    required this.avatarRingColor,
    required this.avatarDotColor,
    required this.childStatusLine,
    required this.connPillOn,
    required this.connPillText,
    required this.locLabel,
    required this.locValue,
    required this.locTime,
  });
}

/// Resolves both content models for a given [ChildAlertStatus],
/// mirroring the original `setState(state)` function line for line.
class ChildAlertContent {
  ChildAlertContent._();

  static AlertStateContent forStatus(ChildAlertStatus status, bool isLight, String Function(String) t) {
    switch (status) {
      case ChildAlertStatus.active:
        return AlertStateContent(
          title: t('childAlert_activeTitle'),
          meta: [
            RichSegment(t('childAlert_activeMetaTriggeredAt')),
            RichSegment(t('childAlert_activeMetaTime'), bold: true),
            RichSegment(t('childAlert_metaSourceSep')),
            RichSegment(t('childAlert_metaSource'), bold: true),
          ],
          severityVisible: true,
          guidance: [
            RichSegment(t('childAlert_activeGuidanceBold'), bold: true),
            RichSegment(t('childAlert_activeGuidanceRest')),
          ],
          actionsVisible: true,
          locationVisible: true,
          resolvedVisible: false,
          closeButtonVisible: false,
          navigateDisabled: false,
          ringPulseActive: true,
          bannerBackground: ChildDevColors.warningBg(isLight),
          bannerBorder: ChildDevColors.warningBorder(isLight),
          iconWrapBackground: ChildDevColors.warningIconWrapBg(isLight),
          titleColor: ChildDevColors.warning,
          screenBorderColor: ChildDevColors.screenBorderActive(isLight),
          brandDotColor: ChildDevColors.warningBright,
        );

      case ChildAlertStatus.found:
        return AlertStateContent(
          title: t('childAlert_foundTitle'),
          meta: [
            RichSegment(t('childAlert_foundMetaConfirmedAt')),
            RichSegment(t('childAlert_foundMetaTime'), bold: true),
            RichSegment(t('childAlert_metaSourceSep')),
            RichSegment(t('childAlert_metaSource'), bold: true),
          ],
          severityVisible: false,
          guidance: [
            RichSegment(t('childAlert_foundGuidanceBold'), bold: true),
            RichSegment(t('childAlert_foundGuidanceRest')),
          ],
          actionsVisible: false,
          locationVisible: true,
          resolvedVisible: false,
          closeButtonVisible: true,
          navigateDisabled: false,
          ringPulseActive: false,
          bannerBackground: ChildDevColors.successBg(isLight),
          bannerBorder: ChildDevColors.successBorder(isLight),
          iconWrapBackground: ChildDevColors.successIconWrapBg(isLight),
          titleColor: ChildDevColors.success,
          screenBorderColor: ChildDevColors.screenBorderFound(isLight),
          brandDotColor: ChildDevColors.success,
        );

      case ChildAlertStatus.resolved:
        return AlertStateContent(
          title: t('childAlert_resolvedTitle'),
          meta: [
            RichSegment(t('childAlert_resolvedMetaClosedAt')),
            RichSegment(t('childAlert_resolvedMetaTime'), bold: true),
            RichSegment(t('childAlert_resolvedMetaReviewedBySep')),
            RichSegment(t('childAlert_resolvedMetaReviewedBy'), bold: true),
          ],
          severityVisible: false,
          guidance: [
            RichSegment(t('childAlert_resolvedGuidance')),
          ],
          actionsVisible: false,
          locationVisible: false,
          resolvedVisible: true,
          closeButtonVisible: true,
          navigateDisabled: false,
          ringPulseActive: false,
          bannerBackground: ChildDevColors.card(isLight),
          bannerBorder: ChildDevColors.hairline(isLight),
          iconWrapBackground: ChildDevColors.cardRaised(isLight),
          titleColor: ChildDevColors.textHi(isLight),
          screenBorderColor: ChildDevColors.screenBorderResolved(isLight),
          brandDotColor: ChildDevColors.textLow(isLight),
        );

      case ChildAlertStatus.unavailable:
        return AlertStateContent(
          title: t('childAlert_unavailableTitle'),
          meta: [
            RichSegment(t('childAlert_unavailableMetaLastSignal')),
            RichSegment(t('childAlert_activeMetaTime'), bold: true),
            RichSegment(t('childAlert_metaSourceSep')),
            RichSegment(t('childAlert_metaSource'), bold: true),
          ],
          severityVisible: true,
          guidance: [
            RichSegment(t('childAlert_unavailableGuidanceBold'), bold: true),
            RichSegment(t('childAlert_unavailableGuidanceRest')),
          ],
          actionsVisible: true,
          locationVisible: true,
          resolvedVisible: false,
          closeButtonVisible: false,
          navigateDisabled: true,
          ringPulseActive: false,
          bannerBackground: ChildDevColors.offlineBg(isLight),
          bannerBorder: ChildDevColors.offlineBorder(isLight),
          iconWrapBackground: ChildDevColors.offlineIconWrapBg(isLight),
          titleColor: ChildDevColors.textMid(isLight),
          screenBorderColor: ChildDevColors.screenBorderUnavailable(isLight),
          brandDotColor: ChildDevColors.offline,
        );
    }
  }

  /// Returns the sticky fields for [status], or `null` when
  /// transitioning to [ChildAlertStatus.resolved] — signaling the
  /// caller to leave the previous sticky values untouched, exactly
  /// as the original `setState('resolved')` branch does.
  static AlertStickyContent? stickyForStatus(ChildAlertStatus status, String Function(String) t) {
    switch (status) {
      case ChildAlertStatus.active:
        return AlertStickyContent(
          avatarRingColor: ChildDevColors.warningBright,
          avatarDotColor: ChildDevColors.warningBright,
          childStatusLine: t('childAlertSticky_activeStatusLine'),
          connPillOn: true,
          connPillText: t('childAlertSticky_connectedLabel'),
          locLabel: t('childAlertSticky_lastKnownLocLabel'),
          locValue: t('childAlertSticky_outerConcourseValue'),
          locTime: t('childAlertSticky_activeLocTime'),
        );

      case ChildAlertStatus.found:
        return AlertStickyContent(
          avatarRingColor: ChildDevColors.success,
          avatarDotColor: ChildDevColors.success,
          childStatusLine: t('childAlertSticky_foundStatusLine'),
          connPillOn: true,
          connPillText: t('childAlertSticky_connectedLabel'),
          locLabel: t('childAlertSticky_currentLocLabel'),
          locValue: t('childAlertSticky_foundLocValue'),
          locTime: t('childAlertSticky_foundLocTime'),
        );

      case ChildAlertStatus.unavailable:
        return AlertStickyContent(
          avatarRingColor: ChildDevColors.offline,
          avatarDotColor: ChildDevColors.offline,
          childStatusLine: t('childAlertSticky_unavailableStatusLine'),
          connPillOn: false,
          connPillText: t('childAlertSticky_disconnectedLabel'),
          locLabel: t('childAlertSticky_lastKnownLocLabel'),
          locValue: t('childAlertSticky_outerConcourseValue'),
          locTime: t('childAlertSticky_unavailableLocTime'),
        );

      case ChildAlertStatus.resolved:
        return null;
    }
  }
}

