/// The three states the Child Safety screen can render, matching the
/// original prototype's `setState('normal' | 'warning' | 'offline')`.
enum ChildStatusState { normal, warning, offline }

/// A single item in the activity timeline.
@immutable
class TimelineEntry {
  final String location;
  final String time;

  const TimelineEntry({required this.location, required this.time});
}

/// All display data for one [ChildStatusState] — every field that changes
/// across the profile card, location card, safety-zone card, and activity
/// card when the state changes.
@immutable
class ChildStatusData {
  final Color ringColor;
  final Color dotColor;
  final String connectionLabel;

  final Color bannerBackground;
  final Color bannerForeground;
  final bool bannerPulseBlinks;
  final String statusText;
  final String statusSub;

  final String locationValue;
  final String locationTime;

  final Color zoneStatusColor;
  final String zoneStatusText;
  final String zoneSub;

  final String lastSeen;
  final String checkInText;
  final Color checkInColor;

  final bool quickActionsDisabled;

  const ChildStatusData({
    required this.ringColor,
    required this.dotColor,
    required this.connectionLabel,
    required this.bannerBackground,
    required this.bannerForeground,
    required this.bannerPulseBlinks,
    required this.statusText,
    required this.statusSub,
    required this.locationValue,
    required this.locationTime,
    required this.zoneStatusColor,
    required this.zoneStatusText,
    required this.zoneSub,
    required this.lastSeen,
    required this.checkInText,
    required this.checkInColor,
    required this.quickActionsDisabled,
  });
}

