  ChildSafetyData._();

  static String brandLabel(String Function(String) t) => t('childSafety_brandLabel');

  static String title(String Function(String) t) => t('childSafety_pageTitle');
  static String subtitle(String Function(String) t) => t('childSafety_pageSubtitle');

  static String childInitials(String Function(String) t) => t('childSafety_childInitials');
  static String childName(String Function(String) t) => t('childSafety_childName');
  static String ageGroup(String Function(String) t) => t('childSafety_ageGroup');

  static String locationSectionLabel(String Function(String) t) => t('childSafety_locationSectionLabel');
  static String locationLabel(String Function(String) t) => t('childAlertSticky_currentLocLabel');
  static String locationTimeLabel(String Function(String) t) => t('childSafety_lastUpdateLabel');

  static String zoneSectionLabel(String Function(String) t) => t('childSafety_zoneSectionLabel');
  static String zoneTitle(String Function(String) t) => t('childSafety_zoneTitle');

  static String activitySectionLabel(String Function(String) t) => t('childSafety_activitySectionLabel');
  static String lastSeenLabel(String Function(String) t) => t('childSafety_lastSeenLabel');
  static String checkInLabel(String Function(String) t) => t('childSafety_checkInLabel');

  static String actionsSectionLabel(String Function(String) t) => t('childSafety_actionsSectionLabel');
  static String callChildLabel(String Function(String) t) => t('childSafety_callChildLabel');
  static String locateChildLabel(String Function(String) t) => t('childSafety_locateChildLabel');
  static String checkInRequestLabel(String Function(String) t) => t('childSafety_checkInRequestLabel');
  static String emergencyAlertLabel(String Function(String) t) => t('childSafety_emergencyAlertLabel');

  static List<TimelineEntry> timeline(String Function(String) t) => [
    TimelineEntry(location: t('childSafety_timeline1Location'), time: t('childSafety_timeline1Time')),
    TimelineEntry(location: t('childSafety_timeline2Location'), time: t('childSafety_timeline2Time')),
    TimelineEntry(location: t('childSafety_timeline3Location'), time: t('childSafety_timeline3Time')),
  ];

  static ChildStatusData normal(bool isLight, String Function(String) t) => ChildStatusData(
    ringColor: ChildDevColors.success,
    dotColor: ChildDevColors.success,
    connectionLabel: t('childAlertSticky_connectedLabel'),
    bannerBackground: ChildDevColors.successBg(isLight),
    bannerForeground: ChildDevColors.success,
    bannerPulseBlinks: false,
    statusText: t('childSafety_normalStatusText'),
    statusSub: t('childSafety_normalStatusSub'),
    locationValue: t('childSafety_normalLocationValue'),
    locationTime: t('childSafety_normalLocationTime'),
    zoneStatusColor: ChildDevColors.success,
    zoneStatusText: t('childSafety_normalZoneStatusText'),
    zoneSub: t('childSafety_normalZoneSub'),
    lastSeen: t('childSafety_normalLastSeen'),
    checkInText: t('childSafety_normalCheckInText'),
    checkInColor: ChildDevColors.success,
    quickActionsDisabled: false,
  );

  static ChildStatusData warning(bool isLight, String Function(String) t) => ChildStatusData(
    ringColor: ChildDevColors.warning,
    dotColor: ChildDevColors.warning,
    connectionLabel: t('childSafety_warningConnLabel'),
    bannerBackground: ChildDevColors.warningBg(isLight),
    bannerForeground: ChildDevColors.warning,
    bannerPulseBlinks: true,
    statusText: t('childSafety_warningStatusText'),
    statusSub: t('childSafety_warningStatusSub'),
    locationValue: t('childSafety_warningLocationValue'),
    locationTime: t('childSafety_warningLocationTime'),
    zoneStatusColor: ChildDevColors.warning,
    zoneStatusText: t('childSafety_warningStatusText'),
    zoneSub: t('childSafety_warningZoneSub'),
    lastSeen: t('childSafety_warningLastSeen'),
    checkInText: t('childSafety_warningCheckInText'),
    checkInColor: ChildDevColors.warning,
    quickActionsDisabled: false,
  );

  static ChildStatusData offline(bool isLight, String Function(String) t) => ChildStatusData(
    ringColor: ChildDevColors.offline,
    dotColor: ChildDevColors.offline,
    connectionLabel: t('childAlertSticky_disconnectedLabel'),
    bannerBackground: ChildDevColors.offlineBg(isLight),
    bannerForeground: ChildDevColors.textMid(isLight),
    bannerPulseBlinks: false,
    statusText: t('childSafety_offlineStatusText'),
    statusSub: t('childSafety_offlineStatusSub'),
    locationValue: t('childSafety_offlineLocationValue'),
    locationTime: t('childSafety_offlineLocationTime'),
    zoneStatusColor: ChildDevColors.textMid(isLight),
    zoneStatusText: t('childSafety_offlineZoneStatusText'),
    zoneSub: t('childSafety_offlineZoneSub'),
    lastSeen: t('childSafety_offlineLastSeen'),
    checkInText: t('childSafety_offlineCheckInText'),
    checkInColor: ChildDevColors.textLow(isLight),
    quickActionsDisabled: true,
  );

  static ChildStatusData forState(ChildStatusState state, bool isLight, String Function(String) t) {
    switch (state) {
      case ChildStatusState.normal:
        return normal(isLight, t);
      case ChildStatusState.warning:
        return warning(isLight, t);
      case ChildStatusState.offline:
        return offline(isLight, t);
    }
  }
}

// ---------------------------------------------------------------
// from: lib/child_dev/child_alert/widgets/pressable_scale.dart
// ---------------------------------------------------------------
/// Wraps [child] with the original screen's button press feedback:
/// scale down to 0.97 on press, and spring back over ~150ms — a
/// direct port of:
/// ```js
/// this.style.transform = 'scale(0.97)';
/// setTimeout(() => this.style.transform = '', 150);
/// ```
class PressableScale extends StatefulWidget {
  final Widget child;
  final VoidCallback? onTap;
  final bool disabled;

  const PressableScale({
    super.key,
    required this.child,
    this.onTap,
    this.disabled = false,
  });

  @override
  State<PressableScale> createState() => _PressableScaleState();
}

class _PressableScaleState extends State<PressableScale> {
  bool _pressed = false;

  void _setPressed(bool value) {
    if (_pressed == value) return;
    setState(() => _pressed = value);
  }

  @override
  Widget build(BuildContext context) {
    return IgnorePointer(
      ignoring: widget.disabled,
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTapDown: (_) => _setPressed(true),
        onTapCancel: () => _setPressed(false),
        onTapUp: (_) => _setPressed(false),
        onTap: widget.onTap,
        child: AnimatedScale(
          scale: _pressed ? 0.97 : 1.0,
          duration: const Duration(milliseconds: 150),
          curve: Curves.easeOut,
          child: widget.child,
        ),
      ),
    );
  }
}

