// ---------------------------------------------------------------
/// Renders a list of [RichSegment]s as a single line of mixed
/// plain/bold text, mirroring the original HTML's use of `<b>` tags
/// inside strings like `Triggered at <b>4:52 PM</b>`.
class RichTextLine extends StatelessWidget {
  final List<RichSegment> segments;
  final TextStyle style;
  final TextStyle boldStyle;
  final TextAlign textAlign;

  const RichTextLine({
    super.key,
    required this.segments,
    required this.style,
    required this.boldStyle,
    this.textAlign = TextAlign.start,
  });

  @override
  Widget build(BuildContext context) {
    return RichText(
      textAlign: textAlign,
      text: TextSpan(
        style: style,
        children: [
          for (final segment in segments)
            TextSpan(
              text: segment.text,
              style: segment.bold ? boldStyle : null,
            ),
        ],
      ),
    );
  }
}

