// from: lib/child_dev/child_alert/widgets/action_button.dart
// ---------------------------------------------------------------
/// The three visual variants of `.action-btn` in the original CSS.
enum ActionButtonVariant { standard, primary, critical }

/// A single recommended-action button, e.g. "Navigate to Location"
/// or "Contact Emergency Support". Ports `.action-btn`,
/// `.action-btn.primary-action`, `.action-btn.critical`, and
/// `.action-btn.disabled`.
class ActionButton extends StatelessWidget {
  final IconData icon;
  final String label;
  final ActionButtonVariant variant;
  final bool disabled;
  final VoidCallback? onTap;

  const ActionButton({
    super.key,
    required this.icon,
    required this.label,
    this.variant = ActionButtonVariant.standard,
    this.disabled = false,
    this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final isLight = Theme.of(context).brightness == Brightness.light;
    final bool isPrimary = variant == ActionButtonVariant.primary;
    final bool isCritical = variant == ActionButtonVariant.critical;

    final Color background = isPrimary
        ? ChildDevColors.primary
        : isCritical
            ? ChildDevColors.criticalBg(isLight)
            : ChildDevColors.cardRaised(isLight);
    final Color borderColor = isPrimary
        ? Colors.transparent
        : isCritical
            ? ChildDevColors.criticalBorder(isLight)
            : ChildDevColors.hairline(isLight);
    final Color iconBackground = isPrimary
        ? ChildDevColors.primaryActionIconBg(isLight)
        : isCritical
            ? ChildDevColors.criticalIconBg(isLight)
            : Colors.white;
    final Color iconColor = isPrimary
        ? Colors.white
        : isCritical
            ? ChildDevColors.criticalBright
            : ChildDevColors.primary;
    final Color labelColor = isPrimary
        ? Colors.white
        : isCritical
            ? ChildDevColors.criticalBright
            : ChildDevColors.textHi(isLight);
    final double labelSize = (isPrimary || isCritical) ? 14 : 13;
    final double iconSize = isPrimary ? 17 : (isCritical ? 17 : 16);

    return Opacity(
      opacity: disabled ? 0.4 : 1,
      child: PressableScale(
        disabled: disabled,
        onTap: onTap,
        child: Container(
          width: double.infinity,
          padding: const EdgeInsetsDirectional.symmetric(horizontal: 13, vertical: 15),
          decoration: BoxDecoration(
            color: background,
            border: Border.all(color: borderColor),
            borderRadius: BorderRadius.circular(16),
            boxShadow: [
              if (isPrimary)
                const BoxShadow(
                  color: ChildDevColors.primaryActionShadow,
                  blurRadius: 20,
                  offset: Offset(0, 8),
                )
              else
                const BoxShadow(
                  color: ChildDevColors.softShadow,
                  blurRadius: 8,
                  offset: Offset(0, 2),
                ),
            ],
          ),
          child: Row(
            children: [
              Container(
                width: 36,
                height: 36,
                alignment: Alignment.center,
                decoration: BoxDecoration(
                  color: iconBackground,
                  borderRadius: BorderRadius.circular(10),
                ),
                child: Icon(icon, size: iconSize, color: iconColor),
              ),
              const SizedBox(width: 11),
              Expanded(
                child: Text(
                  label,
                  style: ChildDevTextStyles.actionName(isLight).copyWith(
                    fontSize: labelSize,
                    color: labelColor,
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

