// ---------------------------------------------------------------
// from: lib/child_dev/child_alert/widgets/alert_banner.dart
// ---------------------------------------------------------------
/// The banner at the top of the screen (`#alert-banner`): a chip icon
/// with an animated pulse ring, the alert title, the meta line, and
/// (when relevant) the severity indicator.
class AlertBanner extends StatefulWidget {
  final AlertStateContent content;

  const AlertBanner({super.key, required this.content});

  @override
  State<AlertBanner> createState() => _AlertBannerState();
}

class _AlertBannerState extends State<AlertBanner>
    with SingleTickerProviderStateMixin {
  late final AnimationController _pulseController;

  @override
  void initState() {
    super.initState();
    _pulseController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1800),
    );
    _syncPulse();
  }

  @override
  void didUpdateWidget(covariant AlertBanner oldWidget) {
    super.didUpdateWidget(oldWidget);
    _syncPulse();
  }

  void _syncPulse() {
    if (widget.content.ringPulseActive) {
      if (!_pulseController.isAnimating) {
        _pulseController.repeat();
      }
    } else {
      _pulseController.stop();
      _pulseController.reset();
    }
  }

  @override
  void dispose() {
    _pulseController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final isLight = Theme.of(context).brightness == Brightness.light;
    final content = widget.content;

    return AnimatedContainer(
      duration: const Duration(milliseconds: 350),
      curve: Curves.easeOutCubic,
      padding: const EdgeInsetsDirectional.symmetric(horizontal: 15, vertical: 16),
      margin: const EdgeInsetsDirectional.only(bottom: 18),
      decoration: BoxDecoration(
        color: content.bannerBackground,
        border: Border.all(color: content.bannerBorder),
        borderRadius: BorderRadius.circular(18),
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _AlertIconChip(
            background: content.iconWrapBackground,
            pulseController: _pulseController,
            pulseActive: content.ringPulseActive,
          ),
          const SizedBox(width: 13),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  content.title,
                  style: ChildDevTextStyles.alertTitle.copyWith(
                    color: content.titleColor,
                  ),
                ),
                const SizedBox(height: 4),
                RichTextLine(
                  segments: content.meta,
                  style: ChildDevTextStyles.alertMeta(isLight),
                  boldStyle: ChildDevTextStyles.alertMetaBold(isLight),
                ),
                if (content.severityVisible) const SeverityIndicator(),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

/// The 44x44 rounded chip housing the warning-triangle icon. The
/// icon itself always keeps the same warning color across every
/// state in the original CSS (its `stroke` is a hard-coded
/// `var(--warning)`, never swapped by the state-switch JS) — only
/// the chip's background tint and the pulse ring change per state.
class _AlertIconChip extends StatelessWidget {
  final Color background;
  final AnimationController pulseController;
  final bool pulseActive;

  const _AlertIconChip({
    required this.background,
    required this.pulseController,
    required this.pulseActive,
  });

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      width: 44,
      height: 44,
      child: Stack(
        alignment: Alignment.center,
        children: [
          AnimatedContainer(
            duration: const Duration(milliseconds: 350),
            width: 44,
            height: 44,
            decoration: BoxDecoration(
              color: background,
              borderRadius: BorderRadius.circular(13),
            ),
          ),
          if (pulseActive)
            AnimatedBuilder(
              animation: pulseController,
              builder: (context, _) {
                final double t = pulseController.value;
                final double eased = Curves.easeOut.transform(t);
                return Opacity(
                  opacity: (0.7 * (1 - eased)).clamp(0.0, 0.7),
                  child: Transform.scale(
                    scale: 1.0 + (0.35 * eased),
                    child: Container(
                      width: 44,
                      height: 44,
                      decoration: BoxDecoration(
                        borderRadius: BorderRadius.circular(13),
                        border: Border.all(
                          color: ChildDevColors.warningBright,
                          width: 1.5,
                        ),
                      ),
                    ),
                  ),
                );
              },
            ),
          const Icon(
            Icons.warning_rounded,
            size: 20,
            color: ChildDevColors.warning,
          ),
        ],
      ),
    );
  }
}

