/// A developer-only state switcher, useful for QA-testing this
/// standalone screen without needing a real backend to drive
/// `active` → `found` → `resolved` / `unavailable` transitions.
///
/// This has no equivalent in the original HTML/CSS/JS (which only
/// ever runs `setState('active')` on load); it exists purely to
/// satisfy "test this screen independently" for all 4 dynamic
/// states, and is rendered outside the phone-styled screen frame.
class StateDebugBar extends StatelessWidget {
  final ChildAlertStatus current;
  final ValueChanged<ChildAlertStatus> onSelect;

  const StateDebugBar({
    super.key,
    required this.current,
    required this.onSelect,
  });

  static const Map<ChildAlertStatus, String> _labels = {
    ChildAlertStatus.active: 'Active Alert',
    ChildAlertStatus.found: 'Child Found',
    ChildAlertStatus.resolved: 'Alert Resolved',
    ChildAlertStatus.unavailable: 'Signal Lost',
  };

  @override
  Widget build(BuildContext context) {
    final isLight = Theme.of(context).brightness == Brightness.light;
    return Wrap(
      alignment: WrapAlignment.center,
      spacing: 8,
      runSpacing: 8,
      children: [
        for (final status in ChildAlertStatus.values)
          ChoiceChip(
            label: Text(_labels[status]!),
            selected: current == status,
            selectedColor: ChildDevColors.primary,
            labelStyle: TextStyle(
              color: current == status ? Colors.white : ChildDevColors.textHi(isLight),
              fontWeight: FontWeight.w600,
              fontSize: 12,
            ),
            backgroundColor: ChildDevColors.cardRaised(isLight),
            side: BorderSide(color: ChildDevColors.hairline(isLight)),
            onSelected: (_) => onSelect(status),
          ),
      ],
    );
  }
}

