// ---------------------------------------------------------------
/// The complete, standalone Child Alert screen.
///
/// This widget is entirely self-contained: it does not import or
/// depend on any other AXN Safety screen. It reproduces the original
/// prototype's `setState()` state machine (`active` / `found` /
/// `resolved` / `unavailable`) including its "sticky field" quirk,
/// where the avatar ring/dot color, connection pill, and location
/// values are only reassigned on `active`/`found`/`unavailable` and
/// simply keep their last value when the alert is `resolved`.
class ChildAlertPage extends StatefulWidget {
  /// The state the screen boots into. Defaults to [ChildAlertStatus.active],
  /// matching the original `setState('active')` call at the bottom of
  /// the prototype's `<script>` block.
  final ChildAlertStatus initialStatus;

  /// Whether to render the developer state-switcher below the
  /// screen, for testing this feature in isolation. Has no visual
  /// effect on the screen itself.
  final bool showDebugStateSwitcher;

  /// Fired when the original screen would have called
  /// `AXN.navigate('child-safety', 1300)` — i.e. 1300ms after the
  /// user taps "Close alert". The argument is the target screen id.
  final ValueChanged<String>? onNavigateAway;

  const ChildAlertPage({
    super.key,
    this.initialStatus = ChildAlertStatus.active,
    this.showDebugStateSwitcher = false,
    this.onNavigateAway,
  });

  @override
  State<ChildAlertPage> createState() => _ChildAlertPageState();
}

class _ChildAlertPageState extends State<ChildAlertPage> {
  late ChildAlertStatus _status;
  bool _stickyInitialized = false;

  // "Sticky" fields — only reassigned when the resolver returns a
  // non-null AlertStickyContent (i.e. every status except `resolved`).
  late Color _avatarRingColor;
  late Color _avatarDotColor;
  late String _childStatusLine;
  late bool _connPillOn;
  late String _connPillText;
  late String _locLabel;
  late String _locValue;
  late String _locTime;

  @override
  void initState() {
    super.initState();
    _status = widget.initialStatus;
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (_stickyInitialized) return;
    _stickyInitialized = true;
    final t = AppScope.of(context).t;
    final sticky = ChildAlertContent.stickyForStatus(_status, t) ??
        ChildAlertContent.stickyForStatus(ChildAlertStatus.active, t)!;
    _applySticky(sticky);
  }

  void _applySticky(AlertStickyContent sticky) {
    _avatarRingColor = sticky.avatarRingColor;
    _avatarDotColor = sticky.avatarDotColor;
    _childStatusLine = sticky.childStatusLine;
    _connPillOn = sticky.connPillOn;
    _connPillText = sticky.connPillText;
    _locLabel = sticky.locLabel;
    _locValue = sticky.locValue;
    _locTime = sticky.locTime;
  }

  /// Ports the original `setState(state)` JS function: switches the
  /// current status, and only touches the sticky fields when the
  /// resolver provides new values for the target status.
  void _changeStatus(ChildAlertStatus next) {
    final t = AppScope.of(context).t;
    setState(() {
      _status = next;
      final sticky = ChildAlertContent.stickyForStatus(next, t);
      if (sticky != null) {
        _applySticky(sticky);
      }
      // When `sticky` is null (i.e. next == resolved), the previous
      // sticky values are deliberately left untouched — matching the
      // original JS, which never writes to those DOM nodes in the
      // 'resolved' branch.
    });
  }

  /// Ports the two click listeners originally attached to `#btn-close`:
  /// ```js
  /// el.btnClose.addEventListener('click', () => setState('resolved'));
  /// el.btnClose.addEventListener('click', () => AXN.navigate('child-safety', 1300));
  /// ```
  void _handleCloseAlert() {
    _changeStatus(ChildAlertStatus.resolved);
    Future.delayed(const Duration(milliseconds: 1300), () {
      if (!mounted) return;
      widget.onNavigateAway?.call('child-safety');
    });
  }

  @override
  Widget build(BuildContext context) {
    final isLight = Theme.of(context).brightness == Brightness.light;
    final content = ChildAlertContent.forStatus(_status, isLight, AppScope.of(context).t);

    return Container(
      color: Colors.white,
      child: SingleChildScrollView(
        padding: const EdgeInsetsDirectional.symmetric(vertical: 48, horizontal: 16),
        child: Column(
          children: [
            ConstrainedBox(
              constraints: const BoxConstraints(maxWidth: 412),
              child: AnimatedContainer(
                duration: const Duration(milliseconds: 400),
                curve: Curves.easeOutCubic,
                padding: const EdgeInsetsDirectional.fromSTEB(20, 24, 20, 28),
                decoration: BoxDecoration(
                  color: ChildDevColors.surface(isLight),
                  border: Border.all(color: content.screenBorderColor),
                  borderRadius: BorderRadius.circular(32),
                  boxShadow: const [
                    BoxShadow(
                      color: ChildDevColors.shadowMd,
                      blurRadius: 24,
                      offset: Offset(0, 8),
                    ),
                  ],
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    _TopRow(brandDotColor: content.brandDotColor),
                    const SizedBox(height: 16),
                    AlertBanner(content: content),
                    Padding(
                      padding: const EdgeInsetsDirectional.only(bottom: 18),
                      child: ChildInfoCard(
                        avatarRingColor: _avatarRingColor,
                        avatarDotColor: _avatarDotColor,
                        statusLine: _childStatusLine,
                        connPillOn: _connPillOn,
                        connPillText: _connPillText,
                      ),
                    ),
                    if (content.locationVisible)
                      Padding(
                        padding: const EdgeInsetsDirectional.only(bottom: 18),
                        child: LocationCard(
                          locLabel: _locLabel,
                          locValue: _locValue,
                          locTime: _locTime,
                        ),
                      ),
                    if (content.actionsVisible)
                      Padding(
                        padding: const EdgeInsetsDirectional.only(bottom: 18),
                        child: RecommendedActionsGrid(
                          navigateDisabled: content.navigateDisabled,
                        ),
                      ),
                    if (content.resolvedVisible)
                      const Padding(
                        padding: EdgeInsetsDirectional.only(bottom: 18),
                        child: ResolvedSummaryCard(),
                      ),
                    GuidanceCard(guidance: content.guidance),
                    if (content.closeButtonVisible) ...[
                      const SizedBox(height: 4),
                      _CloseAlertButton(onTap: _handleCloseAlert),
                    ],
                  ],
                ),
              ),
            ),
            if (widget.showDebugStateSwitcher) ...[
              const SizedBox(height: 28),
              StateDebugBar(current: _status, onSelect: _changeStatus),
            ],
          ],
        ),
      ),
    );
  }
}

