class _ActionButtonState extends State<_ActionButton> {
  bool _hovered = false;

  @override
  Widget build(BuildContext context) {
    final isLight = Theme.of(context).brightness == Brightness.light;
    return Opacity(
      opacity: widget.disabled ? 0.45 : 1,
      child: MouseRegion(
        onEnter: (_) => setState(() => _hovered = true),
        onExit: (_) => setState(() => _hovered = false),
        child: Material(
          color: _hovered && !widget.disabled
              ? ChildDevColors.cardRaised(isLight)
              : ChildDevColors.card(isLight),
          borderRadius: BorderRadius.circular(16),
          child: InkWell(
            borderRadius: BorderRadius.circular(16),
            onTap: widget.disabled ? null : widget.onTap,
            child: AnimatedContainer(
              duration: const Duration(milliseconds: 150),
              transform: _hovered && !widget.disabled
                  ? (Matrix4.identity()..translate(0.0, -2.0))
                  : Matrix4.identity(),
              padding: const EdgeInsetsDirectional.only(start: 14, end: 14, top: 14, bottom: 14),
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(16),
                border: Border.all(
                  color: _hovered && !widget.disabled
                      ? ChildDevColors.primary
                      : ChildDevColors.hairline(isLight),
                ),
                boxShadow: [
                  BoxShadow(
                    color: const Color(0xFF14141E)
                        .withValues(alpha: _hovered && !widget.disabled ? 0.07 : 0.04),
                    blurRadius: _hovered && !widget.disabled ? 16 : 8,
                    offset: const Offset(0, 2),
                  ),
                ],
              ),
              child: widget.horizontal
                  ? Row(
                      children: [
                        _iconBox(isLight),
                        const SizedBox(width: 12),
                        Text(widget.label, style: _labelStyle(isLight)),
                      ],
                    )
                  : Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        _iconBox(isLight),
                        const SizedBox(height: 10),
                        Text(widget.label, style: _labelStyle(isLight)),
                      ],
                    ),
            ),
          ),
        ),
      ),
    );
  }

  Widget _iconBox(bool isLight) {
    return Container(
      width: 36,
      height: 36,
      alignment: Alignment.center,
      decoration: BoxDecoration(
        color: ChildDevColors.cardRaised(isLight),
        borderRadius: BorderRadius.circular(10),
      ),
      child: Icon(widget.icon, size: 17, color: ChildDevColors.primary),
    );
  }

  TextStyle _labelStyle(bool isLight) {
    return TextStyle(
      fontSize: 13,
      fontWeight: FontWeight.w600,
      color: ChildDevColors.textHi(isLight),
    );
  }
}

