/// `.status-row` — brand mark (with pulsing dot) + close button.
class StatusTopBar extends StatefulWidget {
  final String brandLabel;
  final VoidCallback? onClose;

  const StatusTopBar({super.key, required this.brandLabel, this.onClose});

  @override
  State<StatusTopBar> createState() => _StatusTopBarState();
}

class _StatusTopBarState extends State<StatusTopBar>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 2400),
  )..repeat();

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final isLight = Theme.of(context).brightness == Brightness.light;
    return Row(
      mainAxisAlignment: MainAxisAlignment.spaceBetween,
      children: [
        Row(
          children: [
            AnimatedBuilder(
              animation: _controller,
              builder: (context, _) {
                final t = (1 - (0.5 - (_controller.value - 0.5).abs()) * 2)
                    .clamp(0.0, 1.0);
                final spread = 3 + (3 * t);
                final opacity = 0.15 - (0.09 * t);
                return Container(
                  width: 6,
                  height: 6,
                  decoration: BoxDecoration(
                    color: ChildDevColors.primary,
                    shape: BoxShape.circle,
                    boxShadow: [
                      BoxShadow(
                        color: ChildDevColors.primary.withValues(alpha: opacity),
                        spreadRadius: spread,
                      ),
                    ],
                  ),
                );
              },
            ),
            const SizedBox(width: 8),
            Text(
              widget.brandLabel.toUpperCase(),
              style: GoogleFonts.ibmPlexMono(
                fontSize: 11,
                letterSpacing: 1.5,
                color: ChildDevColors.textLow(isLight),
              ),
            ),
          ],
        ),
        Material(
          color: Colors.transparent,
          shape: CircleBorder(side: BorderSide(color: ChildDevColors.hairline(isLight))),
          child: InkWell(
            customBorder: const CircleBorder(),
            onTap: widget.onClose,
            child: SizedBox(
              width: 30,
              height: 30,
              child: Icon(Icons.arrow_back_rounded, size: 16, color: ChildDevColors.textLow(isLight)),
            ),
          ),
        ),
      ],
    );
  }
}

