/// The Child Safety screen — parent-facing monitoring dashboard for a
/// connected child. Fully self-contained: no dependency on any other
/// Safety feature.
class ChildSafetyPage extends StatefulWidget {
  /// The status this screen renders. Defaults to normal; swap this in a
  /// real app whenever new telemetry for the child arrives.
  final ChildStatusState initialState;

  final VoidCallback? onClose;
  final VoidCallback? onCallChild;
  final VoidCallback? onLocateChild;
  final VoidCallback? onSendCheckIn;

  /// Called when "Emergency Alert" is tapped. In the integrated app, this
  /// is where navigation to the Child Alert screen should happen.
  final VoidCallback? onEmergencyAlert;

  const ChildSafetyPage({
    super.key,
    this.initialState = ChildStatusState.normal,
    this.onClose,
    this.onCallChild,
    this.onLocateChild,
    this.onSendCheckIn,
    this.onEmergencyAlert,
  });

  @override
  State<ChildSafetyPage> createState() => _ChildSafetyPageState();
}

class _ChildSafetyPageState extends State<ChildSafetyPage> {
  late ChildStatusState _state = widget.initialState;

  @override
  Widget build(BuildContext context) {
    final isLight = Theme.of(context).brightness == Brightness.light;
    final t = AppScope.of(context).t;
    final data = ChildSafetyData.forState(_state, isLight, t);

    return Scaffold(
      backgroundColor: ChildDevColors.bg(isLight),
      body: SafeArea(
        child: SingleChildScrollView(
          padding: const EdgeInsetsDirectional.fromSTEB(20, 26, 20, 30),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              StatusTopBar(
                brandLabel: ChildSafetyData.brandLabel(t),
                onClose: widget.onClose,
              ),
              const SizedBox(height: 20),
              ChildSafetyHeader(
                title: ChildSafetyData.title(t),
                subtitle: ChildSafetyData.subtitle(t),
              ),
              ChildProfileCard(
                initials: ChildSafetyData.childInitials(t),
                name: ChildSafetyData.childName(t),
                ageGroup: ChildSafetyData.ageGroup(t),
                data: data,
              ),
              const SizedBox(height: 18),
              SafetySectionEyebrow(label: ChildSafetyData.locationSectionLabel(t)),
              LiveLocationCard(
                locationLabel: ChildSafetyData.locationLabel(t),
                locationValue: data.locationValue,
                timeLabel: ChildSafetyData.locationTimeLabel(t),
                timeValue: data.locationTime,
              ),
              const SizedBox(height: 18),
              SafetySectionEyebrow(label: ChildSafetyData.zoneSectionLabel(t)),
              SafetyZoneCard(
                zoneTitle: ChildSafetyData.zoneTitle(t),
                statusColor: data.zoneStatusColor,
                statusText: data.zoneStatusText,
                subText: data.zoneSub,
              ),
              const SizedBox(height: 18),
              SafetySectionEyebrow(label: ChildSafetyData.activitySectionLabel(t)),
              ActivityCard(
                lastSeenLabel: ChildSafetyData.lastSeenLabel(t),
                lastSeenValue: data.lastSeen,
                checkInLabel: ChildSafetyData.checkInLabel(t),
                checkInValue: data.checkInText,
                checkInColor: data.checkInColor,
                timeline: ChildSafetyData.timeline(t),
              ),
              const SizedBox(height: 18),
              SafetySectionEyebrow(label: ChildSafetyData.actionsSectionLabel(t)),
              QuickActionsGrid(
                callLabel: ChildSafetyData.callChildLabel(t),
                locateLabel: ChildSafetyData.locateChildLabel(t),
                checkInLabel: ChildSafetyData.checkInRequestLabel(t),
                emergencyLabel: ChildSafetyData.emergencyAlertLabel(t),
                disabled: data.quickActionsDisabled,
                onCall: widget.onCallChild,
                onLocate: widget.onLocateChild,
                onCheckIn: widget.onSendCheckIn,
                onEmergency: widget.onEmergencyAlert,
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ---------------------------------------------------------------
// from: lib/child_dev/child_dev_app.dart
// ---------------------------------------------------------------
/// Single entry point for the merged `child_dev` feature: Child
/// Safety (the parent dashboard) and Child Alert (the emergency
/// screen), wired together the way the original two standalone demos
/// already hinted at:
///
/// - Child Safety's "Emergency Alert" quick action pushes Child Alert.
/// - Child Alert's "Close alert" (after its 1300ms delay, same as the
///   original prototype) pops back to Child Safety.
class ChildDevApp extends StatelessWidget {
  const ChildDevApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'AXN — Child Dev',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        useMaterial3: true,
        scaffoldBackgroundColor: Colors.white,
      ),
      home: const ChildDevHome(),
    );
  }
}

class ChildDevHome extends StatelessWidget {
  const ChildDevHome({super.key});

  @override
  Widget build(BuildContext context) {
    return ChildSafetyPage(
      initialState: ChildStatusState.normal,
      onClose: () => debugPrint('Child Safety closed'),
      onCallChild: () => debugPrint('Call Child tapped'),
      onLocateChild: () => debugPrint('Locate Child tapped'),
      onSendCheckIn: () => debugPrint('Send Check-in Request tapped'),
      onEmergencyAlert: () {
        Navigator.of(context).push(
          MaterialPageRoute(
            builder: (_) => Scaffold(
              backgroundColor: Colors.white,
              body: SafeArea(
                child: ChildAlertPage(
                  initialStatus: ChildAlertStatus.active,
                  onNavigateAway: (targetScreenId) {
                    // Mirrors the original `AXN.navigate('child-safety', 1300)`
                    // bridge call: return to the Child Safety screen.
                    if (Navigator.of(context).canPop()) {
                      Navigator.of(context).pop();
                    }
                  },
                ),
              ),
            ),
          ),
        );
      },
    );
  }
}


// ---------------------------------------------------------------
// entry point (from: lib/main.dart)
// ---------------------------------------------------------------
void main() {
  runApp(const ChildDevApp());
}
